@@ -439,6 +439,20 @@ func (r *run) seenTree() string {
 	return r.pass.Tree
 }

+// bindingRequirements is the block appended to the feedback of a repair round: the requirements
+// the accepted submissions of this review listed, which the next approval must list again. It is
+// empty when nothing was listed.
+func (r *run) bindingRequirements() string {
+	if len(r.sess.Listed) == 0 {
+		return ""
+	}
+	lines := make([]string, len(r.sess.Listed))
+	for i, text := range r.sess.Listed {
+		lines[i] = "- " + strings.Join(strings.Fields(text), " ")
+	}
+	return "\n\nRequirements already listed in this review (your next approval must list each of them, with this text and with evidence observed on the current tree):\n" + strings.Join(lines, "\n")
+}
+
 // deliverySection tells the reviewer that the candidate changed after its contents were
 // delivered, with the exact diff against the seen tree. It is empty when the trees are equal.
 // It also returns the changed paths it computed.
